(function(w){
  const meta={success:{title:'Success',icon:'✓'},error:{title:'Error',icon:'!'},info:{title:'Information',icon:'i'},warning:{title:'Warning',icon:'!'}};
  function root(){let el=document.querySelector('.notify-stack');if(!el){el=document.createElement('div');el.className='notify-stack';el.setAttribute('aria-live','polite');el.setAttribute('aria-atomic','false');document.body.appendChild(el)}return el}
  w.showNotify=function(message,type='info',options={}){type=meta[type]?type:'info';const cfg=meta[type],item=document.createElement('div');item.className='notify-item '+type;item.setAttribute('role',type==='error'?'alert':'status');const icon=document.createElement('div');icon.className='notify-icon';icon.textContent=cfg.icon;const copy=document.createElement('div');copy.className='notify-copy';const strong=document.createElement('strong');strong.textContent=options.title||cfg.title;const span=document.createElement('span');span.textContent=String(message||'');copy.append(strong,span);const close=document.createElement('button');close.type='button';close.className='notify-close';close.setAttribute('aria-label','Close notification');close.textContent='×';item.append(icon,copy,close);root().appendChild(item);let timer;const remove=()=>{clearTimeout(timer);item.classList.add('is-leaving');setTimeout(()=>item.remove(),220)};close.addEventListener('click',remove);timer=setTimeout(remove,Math.max(2200,Number(options.duration||4600)));return item};
})(window);
